import{_ as o,o as e,c as t,ag as i}from"./chunks/framework.D5hoimZQ.js";const q=JSON.parse('{"title":"科学日报 · 2026-09-16（AI 系统架构）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-system-architecture/science-daily-2026-09-16.md","filePath":"topics/ai-system-architecture/science-daily-2026-09-16.md"}'),r={name:"topics/ai-system-architecture/science-daily-2026-09-16.md"};function l(c,a,n,s,u,d){return e(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="科学日报-·-2026-09-16-ai-系统架构" tabindex="-1">科学日报 · 2026-09-16（AI 系统架构） <a class="header-anchor" href="#科学日报-·-2026-09-16-ai-系统架构" aria-label="Permalink to &quot;科学日报 · 2026-09-16（AI 系统架构）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-16.md</code> — 第27期</p></blockquote><hr><h2 id="gpt-6-astra-做器件设计-ai-驱动的二维-cfet-电热协同优化-arxiv-2609-17123" tabindex="-1">GPT-6 Astra 做器件设计：AI 驱动的二维 CFET 电热协同优化（arXiv:2609.17123） <a class="header-anchor" href="#gpt-6-astra-做器件设计-ai-驱动的二维-cfet-电热协同优化-arxiv-2609-17123" aria-label="Permalink to &quot;GPT-6 Astra 做器件设计：AI 驱动的二维 CFET 电热协同优化（arXiv:2609.17123）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-16.md</code> ｜ arXiv: 2609.17123</p></blockquote><ul><li>AI for Science 落到真实器件工程设计：在 12nm，Astra 选择<strong>重新分布的源—互连几何</strong>，协同 Agent 提出<strong>衬底导向散热方案</strong>。</li><li>价值：多 Agent 工作流在给定电热模型里做<strong>结构提案 × 热约束</strong>的协同寻优，展示&quot;AI for Science&quot;对具体硬件设计（而非泛泛科学叙述）的可验证工程输出。</li></ul><h2 id="thinkflow-可自进化的概率潜在记忆助力终身对话-arxiv-2609-17010" tabindex="-1">ThinkFlow：可自进化的概率潜在记忆助力终身对话（arXiv:2609.17010） <a class="header-anchor" href="#thinkflow-可自进化的概率潜在记忆助力终身对话-arxiv-2609-17010" aria-label="Permalink to &quot;ThinkFlow：可自进化的概率潜在记忆助力终身对话（arXiv:2609.17010）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-16.md</code> ｜ arXiv: 2609.17010</p></blockquote><ul><li>痛点：显式文本记忆管线有信息瓶颈，易丢微妙行为/情绪模式，且部署后静态、不自适应。</li><li>ThinkFlow：<strong>可进化的概率潜在记忆</strong>，在隐空间自监督捕获长期对话中的行为与情绪动态 → 终身对话智能体能持续更新记忆、随交互自我演化。</li><li>洞察：把&quot;长记忆&quot;从<strong>文本摘要</strong>升级为<strong>隐空间动态建模</strong>，与本主题 agent 长期记忆 / 状态表示主线强相关。</li></ul><h2 id="repoatlas-用演化多模态仓库视图引导编码-agent-arxiv-2609-16936" tabindex="-1">RepoAtlas：用演化多模态仓库视图引导编码 Agent（arXiv:2609.16936） <a class="header-anchor" href="#repoatlas-用演化多模态仓库视图引导编码-agent-arxiv-2609-16936" aria-label="Permalink to &quot;RepoAtlas：用演化多模态仓库视图引导编码 Agent（arXiv:2609.16936）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-16.md</code> ｜ arXiv: 2609.16936</p></blockquote><ul><li>仓库级 issue 解决难点不在生成补丁，而在<strong>跨相互依赖文件定位代码</strong> + 维护&quot;既充分又聚焦&quot;的仓库上下文。</li><li>RepoAtlas：<strong>演化的多模态仓库视图</strong>引导编码智能体，把跨文件定位与上下文组织转成更可用的表征。</li><li>洞察：呼应本主题编码 agent 工具链主线——&quot;上下文工程的可靠性&quot;比&quot;补丁生成&quot;更决定仓库级自动化成功率。</li></ul><h2 id="skip-自知识引导分步偏好学习压缩-cot-推理-arxiv-2609-17019" tabindex="-1">SKIP：自知识引导分步偏好学习压缩 CoT 推理（arXiv:2609.17019） <a class="header-anchor" href="#skip-自知识引导分步偏好学习压缩-cot-推理-arxiv-2609-17019" aria-label="Permalink to &quot;SKIP：自知识引导分步偏好学习压缩 CoT 推理（arXiv:2609.17019）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-16.md</code> ｜ arXiv: 2609.17019</p></blockquote><ul><li>CoT 有效但常<strong>过度思考</strong>：拉高算力/延迟甚至掉点。</li><li>SKIP：把&quot;简洁推理&quot;当成<strong>偏好对齐问题</strong>来做——自知识引导的分步偏好学习，压缩输出长度时尽量压低准确率损失。</li><li>洞察：属于&quot;推理压缩&quot;这一降低推理成本的主线；与前几期 LOCUS（省 token 低秩后训练）同类诉求，是多条压缩路径的并行探索。</li></ul><h2 id="跨标准-lora-适配器的共享前缀-kv-复用-arxiv-2609-17109" tabindex="-1">跨标准 LoRA 适配器的共享前缀 KV 复用（arXiv:2609.17109） <a class="header-anchor" href="#跨标准-lora-适配器的共享前缀-kv-复用-arxiv-2609-17109" aria-label="Permalink to &quot;跨标准 LoRA 适配器的共享前缀 KV 复用（arXiv:2609.17109）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-09-16.md</code> ｜ arXiv: 2609.17109</p></blockquote><ul><li>常见部署 = 共享主干 + 多个 LoRA 专家在同一上下文作答；朴素服务会为每专家<strong>重复预填充共享前缀</strong>。</li><li>研究现实问题：对<strong>已训练好、未做缓存兼容改造</strong>的标准 LoRA，做共享前缀 KV 跨适配器复用的质量/吞吐/显存权衡。</li><li>洞察：server-side 复用（而非改适配器）是立即可用的省显存手段——延续本主题&quot;省显存放更多模型/调度&quot;主线，与 SQD/SeqMoE（上期）同属推理系统优化连续集。</li></ul><hr><blockquote><p>📎 关联主题：<code>topics/ai-system-architecture/index.md</code> ｜ 第27期 AI 板块</p></blockquote>',20)])])}const p=o(r,[["render",l]]);export{q as __pageData,p as default};
